/** 词表回退链：无对应词表的语言回退英文 */
const FALLBACK = { 'ar': 'en' };

function pickList(locale) {
  const loc = (locale || 'en').split('-')[0];
  if (SAS_WORDS[locale]) return SAS_WORDS[locale];
  if (SAS_WORDS[loc]) return SAS_WORDS[loc];
  if (FALLBACK[locale]) return SAS_WORDS[FALLBACK[locale]];
  return SAS_WORDS['en'];
}

/**
 * 从 SHA-256 摘要推导安全词（每 11 bit 取一词，默认 6 词 = 66 bit）
 * @param {Uint8Array} digest - 32 字节摘要
 * @param {number} count - 词数（默认 6）
 * @param {string} locale - 语言（zh/en/ja/ko/...，无词表回退英文）
 * @returns {string[]}
 */
export function wordsFromDigest(digest, count = 6, locale = 'en') {
  const list = pickList(locale);
  const words = [];
  for (let i = 0; i < count; i++) {
    const bitOffset = i * 11;
    const byteOffset = bitOffset >> 3;
    const shift = bitOffset & 7;
    let idx = ((digest[byteOffset] << 16) | (digest[byteOffset + 1] << 8) | (digest[byteOffset + 2])) >> (13 - shift);
    idx = idx & 0x7ff;
    words.push(list[idx]);
  }
  return words;
}
